// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 10 ether);
        Reverter target = new Reverter();
        vm.deal(address(c), amount);
        vm.prank(c.owner());
        bool ok;
        try c.sendMoney(address(target), amount) { ok = true; } catch { ok = false; }
        assertTrue(ok, "sendMoney must not propagate a reverting target");
    }
}

contract Reverter {
    receive() external payable { revert(); }
    fallback() external payable { revert(); }
}
